// AVX2 lane library for the "simd" code path generated by pcuda_mslgen: 8 CUDA threads per
// 256-bit register, the CPU counterpart of a GPU warp. Each lane performs exactly the IEEE
// operations of one thread in Booth's scalar code, in the same order, so results are
// bit-identical to the booth and native paths. Compile with /arch:AVX2.
//
// Masks are VI values with all bits set in active lanes. Loads and stores touch only active
// lanes, so a kernel faults exactly where the scalar code would.
#pragma once

#include <immintrin.h>
#include <intrin.h>

#include <cstdint>
#include <cstdlib>

#include <math.h>

namespace pcuda::simd {

using VF = __m256;
using VI = __m256i;

constexpr int   kLanes = 8;
constexpr float kTwoPi = 6.28318548f;  // same constant as metal_stdlib / Booth x86

inline VI iota() { return _mm256_setr_epi32(0, 1, 2, 3, 4, 5, 6, 7); }
inline VI splat(int v) { return _mm256_set1_epi32(v); }
inline VF splat(float v) { return _mm256_set1_ps(v); }
inline VI zeroI() { return _mm256_setzero_si256(); }
inline VF zeroF() { return _mm256_setzero_ps(); }
inline VI allOnes() { return _mm256_set1_epi32(-1); }

// ---- masks ----
inline bool any(VI m) { return !_mm256_testz_si256(m, m); }
inline VI   mAnd(VI a, VI b) { return _mm256_and_si256(a, b); }
inline VI   mAndNot(VI c, VI m) { return _mm256_andnot_si256(c, m); }  // m & ~c
inline VI   mNot(VI a) { return _mm256_xor_si256(a, allOnes()); }
inline VI   tailMask(unsigned t0, unsigned n) {  // lanes t0 + l < n
    return _mm256_cmpgt_epi32(splat(static_cast<int>(n - t0)), iota());
}

// ---- blends: take `v` in active lanes, keep `old` elsewhere ----
inline VF blend(VF old, VF v, VI m) { return _mm256_blendv_ps(old, v, _mm256_castsi256_ps(m)); }
inline VI blend(VI old, VI v, VI m) { return _mm256_blendv_epi8(old, v, m); }

// ---- int lanes (wrapping 32-bit arithmetic) ----
inline VI add(VI a, VI b) { return _mm256_add_epi32(a, b); }
inline VI sub(VI a, VI b) { return _mm256_sub_epi32(a, b); }
inline VI mul(VI a, VI b) { return _mm256_mullo_epi32(a, b); }
inline VI band(VI a, VI b) { return _mm256_and_si256(a, b); }
inline VI bor(VI a, VI b) { return _mm256_or_si256(a, b); }
inline VI bxor(VI a, VI b) { return _mm256_xor_si256(a, b); }
inline VI shl(VI a, VI b) { return _mm256_sllv_epi32(a, b); }
inline VI ashr(VI a, VI b) { return _mm256_srav_epi32(a, b); }
inline VI lt(VI a, VI b) { return _mm256_cmpgt_epi32(b, a); }
inline VI gt(VI a, VI b) { return _mm256_cmpgt_epi32(a, b); }
inline VI le(VI a, VI b) { return mNot(gt(a, b)); }
inline VI ge(VI a, VI b) { return mNot(lt(a, b)); }
inline VI eq(VI a, VI b) { return _mm256_cmpeq_epi32(a, b); }
inline VI ne(VI a, VI b) { return mNot(eq(a, b)); }

// Division has no AVX2 instruction: divide lane by lane, active lanes only, so a zero divisor
// faults (EXCEPTION_INT_DIVIDE_BY_ZERO) exactly as the scalar code does.
inline VI div(VI a, VI b, VI m) {
    alignas(32) int x[8], y[8], k[8], r[8] = {};
    _mm256_store_si256(reinterpret_cast<VI*>(x), a);
    _mm256_store_si256(reinterpret_cast<VI*>(y), b);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) r[l] = x[l] / y[l];
    return _mm256_load_si256(reinterpret_cast<const VI*>(r));
}
inline VI rem(VI a, VI b, VI m) {
    alignas(32) int x[8], y[8], k[8], r[8] = {};
    _mm256_store_si256(reinterpret_cast<VI*>(x), a);
    _mm256_store_si256(reinterpret_cast<VI*>(y), b);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) r[l] = x[l] % y[l];
    return _mm256_load_si256(reinterpret_cast<const VI*>(r));
}

// ---- float lanes ----
inline VF add(VF a, VF b) { return _mm256_add_ps(a, b); }
inline VF sub(VF a, VF b) { return _mm256_sub_ps(a, b); }
inline VF mul(VF a, VF b) { return _mm256_mul_ps(a, b); }
inline VF fdiv(VF a, VF b) { return _mm256_div_ps(a, b); }
inline VI lt(VF a, VF b) { return _mm256_castps_si256(_mm256_cmp_ps(a, b, _CMP_LT_OQ)); }
inline VI le(VF a, VF b) { return _mm256_castps_si256(_mm256_cmp_ps(a, b, _CMP_LE_OQ)); }
inline VI gt(VF a, VF b) { return _mm256_castps_si256(_mm256_cmp_ps(a, b, _CMP_GT_OQ)); }
inline VI ge(VF a, VF b) { return _mm256_castps_si256(_mm256_cmp_ps(a, b, _CMP_GE_OQ)); }
inline VI eq(VF a, VF b) { return _mm256_castps_si256(_mm256_cmp_ps(a, b, _CMP_EQ_OQ)); }
inline VI ne(VF a, VF b) { return _mm256_castps_si256(_mm256_cmp_ps(a, b, _CMP_NEQ_UQ)); }
inline VF vsqrt(VF a) { return _mm256_sqrt_ps(a); }
inline VF vfmax(VF a, VF b) { return _mm256_max_ps(a, b); }  // == maxss a, b per lane
inline VF vfmin(VF a, VF b) { return _mm256_min_ps(a, b); }

// Transcendentals: the same CRT call per lane as the scalar paths (bit-identical).
template <float (*F)(float)>
inline VF perLane(VF a) {
    alignas(32) float t[8];
    _mm256_store_ps(t, a);
    for (int l = 0; l < kLanes; ++l) t[l] = F(t[l]);
    return _mm256_load_ps(t);
}
inline float sinTurns(float t) { return ::sinf(t * kTwoPi); }
inline float cosTurns(float t) { return ::cosf(t * kTwoPi); }
inline VF vsin(VF a) { return perLane<sinTurns>(a); }
inline VF vcos(VF a) { return perLane<cosTurns>(a); }
inline VF vexp2(VF a) { return perLane<::exp2f>(a); }
inline VF vlog2(VF a) { return perLane<::log2f>(a); }

// ---- 8-bit dot products (pcuda_dp4a in kernels/llm/matvec_q4x8_q8.cu) ----
// c + sum over the 4 bytes of a (unsigned) times the 4 bytes of b (signed), wrapping 32-bit.
inline int dp4aScalar(int a, int b, int c) {
    c += (a & 255) * ((b << 24) >> 24);
    c += ((a >> 8) & 255) * ((b << 16) >> 24);
    c += ((a >> 16) & 255) * ((b << 8) >> 24);
    c += ((a >> 24) & 255) * (b >> 24);
    return c;
}
inline bool cpuHasAvxVnni() {
    static const bool has = [] {
        int r[4] = {};
        __cpuidex(r, 7, 1);
        return (r[0] & (1 << 4)) != 0;
    }();
    return has;
}
// AVX-VNNI vpdpbusd computes exactly dp4aScalar per lane (u8 x s8, no saturation). Without
// VNNI the same integer result comes from four 32-bit multiplies.
// Generated kernels pick the variant once per launch (template parameter): a runtime check in the
// loop made MSVC spill every vector register around it.
template <bool Vnni>
inline VI vdp4aT(VI c, VI a, VI b) {
    if constexpr (Vnni) {
        return _mm256_dpbusd_avx_epi32(c, a, b);
    } else {
        VI r = c;
        r = add(r, mul(_mm256_and_si256(a, splat(255)), _mm256_srai_epi32(_mm256_slli_epi32(b, 24), 24)));
        r = add(r, mul(_mm256_and_si256(_mm256_srli_epi32(a, 8), splat(255)), _mm256_srai_epi32(_mm256_slli_epi32(b, 16), 24)));
        r = add(r, mul(_mm256_and_si256(_mm256_srli_epi32(a, 16), splat(255)), _mm256_srai_epi32(_mm256_slli_epi32(b, 8), 24)));
        r = add(r, mul(_mm256_srli_epi32(a, 24), _mm256_srai_epi32(b, 24)));
        return r;
    }
}
inline VI vdp4a(VI c, VI a, VI b) {
    if (cpuHasAvxVnni()) return _mm256_dpbusd_avx_epi32(c, a, b);
    VI r = c;
    r = add(r, mul(_mm256_and_si256(a, splat(255)), _mm256_srai_epi32(_mm256_slli_epi32(b, 24), 24)));
    r = add(r, mul(_mm256_and_si256(_mm256_srli_epi32(a, 8), splat(255)), _mm256_srai_epi32(_mm256_slli_epi32(b, 16), 24)));
    r = add(r, mul(_mm256_and_si256(_mm256_srli_epi32(a, 16), splat(255)), _mm256_srai_epi32(_mm256_slli_epi32(b, 8), 24)));
    r = add(r, mul(_mm256_srli_epi32(a, 24), _mm256_srai_epi32(b, 24)));
    return r;
}

// ---- conversions ----
inline VF i2f(VI a) { return _mm256_cvtepi32_ps(a); }   // cvtsi2ss per lane (round to nearest)
inline VI f2i(VF a) { return _mm256_cvttps_epi32(a); }  // truncation, like a C cast
inline VI sext8(VI a) { return _mm256_srai_epi32(_mm256_slli_epi32(a, 24), 24); }
inline VI zext8(VI a) { return _mm256_and_si256(a, _mm256_set1_epi32(0xFF)); }

// ---- memory: varying pointers are a uniform base plus a lane index (in elements) ----
#pragma warning(push)
#pragma warning(disable : 4324)  // VPtr is padded to the 32-byte alignment of its index vector
template <class T>
struct VPtr {
    T* base = nullptr;
    VI idx = _mm256_setzero_si256();
};
template <class T>
inline VPtr<T> gep(T* base, VI idx) { return {base, idx}; }
template <class T>
inline VPtr<T> gep(VPtr<T> p, VI idx) { return {p.base, add(p.idx, idx)}; }
template <class T>
inline VPtr<T> blend(VPtr<T> old, VPtr<T> v, VI m) { return {v.base, blend(old.idx, v.idx, m)}; }
// Same-size pointer reinterpretation (Metal as_type): the element index is unchanged.
template <class T, class U>
inline VPtr<T> ptrcast(VPtr<U> p) {
    static_assert(sizeof(T) == sizeof(U), "as_type between element types of different size");
    return {reinterpret_cast<T*>(p.base), p.idx};
}
#pragma warning(pop)

// Active lanes form base[i0 + l] with lane 0 active: one masked contiguous access.
inline bool contiguous(VI idx, VI m, int* first) {
    const int i0 = _mm256_cvtsi256_si32(idx);
    if (!(_mm256_cvtsi256_si32(m))) return false;
    const VI want = add(splat(i0), iota());
    const VI bad = _mm256_andnot_si256(_mm256_cmpeq_epi32(idx, want), m);
    *first = i0;
    return _mm256_testz_si256(bad, bad);
}
// Gather instructions scale a 32-bit index by 4: keep the byte offset in range.
inline bool gatherSafe(VI idx, VI m) {
    const VI hi = _mm256_cmpgt_epi32(idx, splat((1 << 29) - 1));
    const VI lo = _mm256_cmpgt_epi32(splat(-(1 << 29)), idx);
    const VI bad = _mm256_and_si256(_mm256_or_si256(hi, lo), m);
    return _mm256_testz_si256(bad, bad);
}

inline VF load(VPtr<float> p, VI m) {
    int i0;
    if (contiguous(p.idx, m, &i0)) return _mm256_maskload_ps(p.base + i0, m);
    if (gatherSafe(p.idx, m))
        return _mm256_mask_i32gather_ps(_mm256_setzero_ps(), p.base, p.idx, _mm256_castsi256_ps(m), 4);
    alignas(32) int ix[8], k[8];
    alignas(32) float r[8] = {};
    _mm256_store_si256(reinterpret_cast<VI*>(ix), p.idx);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) r[l] = p.base[ix[l]];
    return _mm256_load_ps(r);
}
inline VI load(VPtr<int> p, VI m) {
    int i0;
    if (contiguous(p.idx, m, &i0)) return _mm256_maskload_epi32(p.base + i0, m);
    if (gatherSafe(p.idx, m)) return _mm256_mask_i32gather_epi32(zeroI(), p.base, p.idx, m, 4);
    alignas(32) int ix[8], k[8], r[8] = {};
    _mm256_store_si256(reinterpret_cast<VI*>(ix), p.idx);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) r[l] = p.base[ix[l]];
    return _mm256_load_si256(reinterpret_cast<const VI*>(r));
}
// Bytes: AVX2 has no byte gather. Gather the aligned 32-bit word holding each byte (one
// instruction) and shift the byte out. An aligned word never crosses a page boundary, so this
// faults only where the byte itself would; masked-off lanes are not read at all. (It may read
// up to 3 bytes of the same word outside a heap block, which is harmless at page granularity.)
// Lanes hold the raw byte zero-extended; the following cast applies the signedness.
inline VI load(VPtr<char> p, VI m) {
    // All 8 lanes active and reading consecutive bytes (interleaved layouts): one 8-byte load.
    // Only with a full mask, so a partial tail group never reads past what the threads would.
    int i0;
    if (_mm256_movemask_ps(_mm256_castsi256_ps(m)) == 0xFF && contiguous(p.idx, m, &i0))
        return _mm256_cvtepu8_epi32(_mm_loadl_epi64(reinterpret_cast<const __m128i*>(p.base + i0)));
    const uintptr_t b = reinterpret_cast<uintptr_t>(p.base);
    const VI big = _mm256_cmpgt_epi32(p.idx, splat(0x7FFFFFF0));
    const VI neg = _mm256_cmpgt_epi32(splat(-0x7FFFFFF0), p.idx);
    const VI bad = _mm256_and_si256(_mm256_or_si256(big, neg), m);
    if (_mm256_testz_si256(bad, bad)) {
        const VI off = add(p.idx, splat(static_cast<int>(b & 3)));  // offset from the aligned base
        const int* wbase = reinterpret_cast<const int*>(b & ~uintptr_t(3));
        const VI w = _mm256_mask_i32gather_epi32(zeroI(), wbase, _mm256_and_si256(off, splat(~3)), m, 1);
        const VI sh = _mm256_slli_epi32(_mm256_and_si256(off, splat(3)), 3);
        return _mm256_and_si256(_mm256_srlv_epi32(w, sh), splat(0xFF));
    }
    alignas(32) int ix[8], k[8], r[8] = {};
    _mm256_store_si256(reinterpret_cast<VI*>(ix), p.idx);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    const auto* bp = reinterpret_cast<const unsigned char*>(p.base);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) r[l] = bp[ix[l]];
    return _mm256_load_si256(reinterpret_cast<const VI*>(r));
}

// Stores in lane (= thread) order, so overlapping writes resolve as in the scalar code.
inline void store(VPtr<float> p, VF v, VI m) {
    int i0;
    if (contiguous(p.idx, m, &i0)) {
        _mm256_maskstore_ps(p.base + i0, m, v);
        return;
    }
    alignas(32) int ix[8], k[8];
    alignas(32) float x[8];
    _mm256_store_si256(reinterpret_cast<VI*>(ix), p.idx);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    _mm256_store_ps(x, v);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) p.base[ix[l]] = x[l];
}
inline void store(VPtr<int> p, VI v, VI m) {
    int i0;
    if (contiguous(p.idx, m, &i0)) {
        _mm256_maskstore_epi32(p.base + i0, m, v);
        return;
    }
    alignas(32) int ix[8], k[8], x[8];
    _mm256_store_si256(reinterpret_cast<VI*>(ix), p.idx);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    _mm256_store_si256(reinterpret_cast<VI*>(x), v);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) p.base[ix[l]] = x[l];
}
inline void store(VPtr<char> p, VI v, VI m) {
    alignas(32) int ix[8], k[8], x[8];
    _mm256_store_si256(reinterpret_cast<VI*>(ix), p.idx);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    _mm256_store_si256(reinterpret_cast<VI*>(x), v);
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) p.base[ix[l]] = static_cast<char>(x[l]);
}

// pcuda_aligned8(x) in a kernel promises x >= 0 and x % 8 == 0; the generated code relies on it
// (x-based divisions stay uniform across lanes), so a broken promise faults instead of
// producing wrong results. The fault guard reports it like any kernel fault.
inline int aligned8(int x) {
    if (x < 0 || (x & 7) != 0) __debugbreak();
    return x;
}

// Software prefetch for streaming loads (emitted before contiguous loads in loops). A prefetch
// never faults, so reading ahead of the end of a buffer is harmless. Distance: 2 KB (measured:
// 1.5-8 KB all ~3-4% faster LLM decode); PCUDA_PREFETCH_BYTES overrides it (0 = off).
inline const int kPrefetchBytes = [] {
    char* v = nullptr;
    size_t len = 0;
    int r = 2048;
    if (_dupenv_s(&v, &len, "PCUDA_PREFETCH_BYTES") == 0 && v) r = std::atoi(v);
    free(v);
    return r;
}();
template <class T>
inline void prefetchAhead(const T* p) {
    if (kPrefetchBytes) _mm_prefetch(reinterpret_cast<const char*>(p) + kPrefetchBytes, _MM_HINT_T0);
}

// ---- affine values: lane l holds b + s*l, kept as the scalar b while s is a compile-time constant ----
inline VI affine(int b, int s) { return add(splat(b), _mm256_mullo_epi32(iota(), splat(s))); }
template <class T>
inline VPtr<T> affinePtr(T* p, int s) { return {p, _mm256_mullo_epi32(iota(), splat(s))}; }
// Consecutive elements p[0..7] (stride 1): no index checks; masked lanes are not touched.
inline VF loadc(float* p, VI m) { return _mm256_maskload_ps(p, m); }
inline VI loadc(int* p, VI m) { return _mm256_maskload_epi32(p, m); }
inline VI loadc(char* p, VI m) {
    if (_mm256_movemask_ps(_mm256_castsi256_ps(m)) == 0xFF)
        return _mm256_cvtepu8_epi32(_mm_loadl_epi64(reinterpret_cast<const __m128i*>(p)));
    return load(VPtr<char>{p, iota()}, m);
}
inline void storec(float* p, VF v, VI m) { _mm256_maskstore_ps(p, m, v); }
inline void storec(int* p, VI v, VI m) { _mm256_maskstore_epi32(p, m, v); }
inline void storec(char* p, VI v, VI m) { store(VPtr<char>{p, iota()}, v, m); }

// A uniform address written by several threads keeps the last (highest) active lane's value.
inline float lastActive(VF v, VI m) {
    alignas(32) float x[8];
    alignas(32) int k[8];
    _mm256_store_ps(x, v);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    float r = 0;
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) r = x[l];
    return r;
}
inline int lastActive(VI v, VI m) {
    alignas(32) int x[8], k[8];
    _mm256_store_si256(reinterpret_cast<VI*>(x), v);
    _mm256_store_si256(reinterpret_cast<VI*>(k), m);
    int r = 0;
    for (int l = 0; l < kLanes; ++l)
        if (k[l]) r = x[l];
    return r;
}

} // namespace pcuda::simd
